const response = $input.first().json;
let content = {};

try {
  // Gemini API response structure
  const text = response.candidates[0].content.parts[0].text;
  content = JSON.parse(text);
} catch (e) {
  // Fallback content if parsing fails
  content = {
    topic: 'AI Innovation 2025',
    facebook: '🚀 Discover how AI is transforming businesses in 2025. From automation to insights, the future is here!',
    instagram: '✨ AI Revolution Alert! 🤖 Swipe to see how artificial intelligence is changing everything we know about tech 💡',
    tiktok: 'POV: AI just made your job 10x easier 🤯 #AITech #FutureTech',
    linkedin: 'The convergence of AI and enterprise technology is creating unprecedented opportunities for innovation.',
    hashtags: '#AI #Innovation #TechTrends #DigitalTransformation #FutureTech',
    bestTime: '10:00 AM EST'
  };
}

// Build platforms array based on enabled platforms
const platforms = [];

if (__node('Default_Settings').item.json.ENABLE_FACEBOOK === 'true') {
  platforms.push({
    platform: 'facebook',
    content: content.facebook,
    enabled: true
  });
}

if (__node('Default_Settings').item.json.ENABLE_INSTAGRAM === 'true') {
  platforms.push({
    platform: 'instagram',
    content: content.instagram,
    enabled: true
  });
}

if (__node('Default_Settings').item.json.ENABLE_TIKTOK === 'true') {
  platforms.push({
    platform: 'tiktok',
    content: content.tiktok,
    enabled: true
  });
}

if (__node('Default_Settings').item.json.ENABLE_LINKEDIN === 'true') {
  platforms.push({
    platform: 'linkedin',
    content: content.linkedin,
    enabled: true
  });
}

return [{
  json: {
    ...content,
    enabledPlatforms: platforms,
    platformCount: platforms.length
  }
}];
})();
return { body: __unwrap(__result) };

